-- Serenity Secrets: production persistence schema. Apply with Supabase migrations.
create type app_role as enum ('admin', 'operator', 'customer');
create type booking_status as enum ('draft','held','pending_payment','confirmed','cancelled','refunded');
create type payment_status as enum ('pending','processing','paid','failed','cancelled','refunded');

create table profiles (id uuid primary key references auth.users on delete cascade, role app_role not null default 'customer', full_name text, created_at timestamptz not null default now());
create table destinations (id uuid primary key default gen_random_uuid(), slug text unique not null, published boolean not null default false, created_at timestamptz not null default now());
create table cities (id uuid primary key default gen_random_uuid(), destination_id uuid references destinations on delete cascade, slug text unique not null, published boolean not null default false);
create table experiences (id uuid primary key default gen_random_uuid(), city_id uuid references cities, slug text unique not null, supplier_base_usd_cents integer not null check (supplier_base_usd_cents >= 0), markup_percent numeric(5,2), capacity integer not null check (capacity > 0), published boolean not null default false, media_authorized boolean not null default false, created_at timestamptz not null default now());
create table experience_translations (experience_id uuid references experiences on delete cascade, locale text check (locale in ('en','de','ar')), title text not null, excerpt text, description text, primary key(experience_id,locale));
create table media_assets (id uuid primary key default gen_random_uuid(), experience_id uuid references experiences on delete cascade, kind text check (kind in ('reel','poster','gallery')), provider text, asset_url text not null, authorized boolean not null default false, sort_order integer not null default 0);
create table availability_rules (id uuid primary key default gen_random_uuid(), experience_id uuid references experiences on delete cascade, starts_on date not null, ends_on date, weekdays smallint[] not null, capacity integer, selling_usd_cents integer, active boolean not null default true);
create table availability_overrides (experience_id uuid references experiences on delete cascade, date date not null, status text check (status in ('open','blocked','sold_out')), capacity integer, selling_usd_cents integer, primary key(experience_id,date));
create table fx_rates (id uuid primary key default gen_random_uuid(), base_currency text not null default 'USD', quote_currency text not null, rate numeric(18,8) not null, source text not null, effective_on date not null, manual_override boolean not null default false, unique(base_currency,quote_currency,effective_on));
create table bookings (id uuid primary key default gen_random_uuid(), reference text unique not null, customer_email text not null, travel_start date not null, adults integer not null, display_currency text not null, display_total_cents integer not null, charged_usd_cents integer not null, fx_rate numeric(18,8) not null, status booking_status not null default 'draft', hold_expires_at timestamptz, created_at timestamptz not null default now());
create table booking_items (id uuid primary key default gen_random_uuid(), booking_id uuid references bookings on delete cascade, experience_id uuid references experiences, travel_date date not null, experience_name_snapshot text not null, unit_usd_cents integer not null, quantity integer not null, pickup_snapshot text, starts_at time);
create table payment_transactions (id uuid primary key default gen_random_uuid(), booking_id uuid references bookings on delete cascade, provider text not null, provider_reference text unique, idempotency_key text unique not null, status payment_status not null default 'pending', amount_usd_cents integer not null, raw_event jsonb, created_at timestamptz not null default now());
alter table experiences enable row level security; alter table bookings enable row level security;
create policy "Published experiences are readable" on experiences for select using (published = true);
create policy "Customers read their bookings" on bookings for select using (auth.jwt()->>'email' = customer_email);
